/**
 * @summary Get all pending approvals across all charters
 */
export const getGetPendingApprovalsUrl = (
  params?: GetPendingApprovalsParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/dashboard/pending-approvals?${stringifiedParams}`
    : `/api/dashboard/pending-approvals`;
};

export const getPendingApprovals = async (
  params?: GetPendingApprovalsParams,
  options?: RequestInit,
): Promise<Approval[]> => {
  return customFetch<Approval[]>(getGetPendingApprovalsUrl(params), {
    ...options,
    method: "GET",
  });
};

